/bin/bash -lc "python3 - <<'PY'
import re, pathlib

def normalize(s):
    return ' '.join(s.split())

MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December']
MONTH_RE = r'(?:' + '|'.join(MONTHS) + r')'
ISSUE_RE = re.compile(r'\\b(March|June|September|December)\\s+(20\\d{2})\\b', re.I)


def extract_issue(text, doc_name=None):
    # Prefer an early explicit month/year in the header.
    head = '\\n'.join(text.splitlines()[:80])
    m = ISSUE_RE.search(head)
    if m:
        return m.group(1).title() + ' ' + m.group(2)
    if doc_name:
        m = re.search(r'treasury_bulletin_(\\d{4})_(\\d{2})', doc_name)
        if m:
            y, mm = m.groups()
            month = {'03':'March','06':'June','09':'September','12':'December'}.get(mm)
            if month:
                return f'{month} {y}'
    return 'NOT_FOUND'


def section(text, start, end=None):
    i = text.find(start)
    if i < 0:
        return ''
    j = text.find(end, i+len(start)) if end else -1
    if j < 0:
        return text[i:]
    return text[i:j]


def last_match_number(patterns, text, flags=re.I|re.S):
    best = None
    for pat in patterns:
        for m in re.finditer(pat, text, flags):
            best = m
    return best


def parse_gdp(text):
    flat = normalize(text)
    pats = [
        r'real GDP (?:advanced|grew|increased|rose|expanded|accelerated)\\s+([\\d.]+) percent(?: at an annual rate)?(?: in| during) the (first|second|third|fourth) quarter of (20\\d{2})',
        r'According to the ["'^.]{0,80}? real GDP (?:advanced|grew|increased|rose|expanded|accelerated)'"\\s+([\\d.]+) percent(?: at an annual rate)?(?: in| during) the (first|second|third|fourth) quarter of (20\\d{2})',
        r'real GDP (?:advanced|grew|increased|rose|expanded|accelerated)\\s+([\\d.]+) percent(?: at an annual rate)?',
    ]
    m = last_match_number(pats, flat)
    return m.group(1) if m else 'NOT_FOUND'


def parse_unemployment(text):
    flat = normalize(text)
    pats = [
        r'unemployment rate["'^.]{0,200}?(?:reaching|stood at|was|rose to|declined to|fell to|dropped to|peaked at|trended lower, reaching|trended lower to|moved to|remained at)'"\\s+([\\d.]+) percent\\s+(?:in|as of)\\s+([A-Za-z]+\\s+20\\d{2})',
        r'unemployment rate["'^.]{0,200}?(['"\\d.]+) percent\\s+(?:in|as of)\\s+([A-Za-z]+\\s+20\\d{2})',
    ]
    matches=[]
    for pat in pats:
        matches.extend(list(re.finditer(pat, flat, re.I)))
    if not matches:
        return 'NOT_FOUND'
    m = max(matches, key=lambda m: m.start())
    return m.group(1)


def parse_payroll(text):
    # Focus on the labor-market narrative.
    flat = normalize(text)
    start = flat.find('Labor Markets')
    if start < 0:
        return 'NOT_FOUND'
    end = flat.find('Inflation', start)
    if end < 0:
        end = flat.find('Consumer and Business Sentiment', start)
    if end < 0:
        end = len(flat)
    sec = flat[start:end]
    pats = [
        r'average monthly gain of\\s+([\\d,]+) jobs',
        r'average monthly loss of\\s+([\\d,]+) jobs',
        r'average monthly gain of\\s+([\\d,]+) per month',
        r'average monthly\\s+([\\d,]+) jobs',
        r'average of\\s+([\\d,]+) jobs in',
        r'([\\d,]+) jobs on average',
        r'([\\d,]+) per month on average',
        r'average monthly growth of\\s+([\\d,]+)',
    ]
    ms=[]
    for pat in pats:
        ms.extend(list(re.finditer(pat, sec, re.I)))
    if not ms:
        return 'NOT_FOUND'
    m = max(ms, key=lambda m: m.start())
    return m.group(1)


def parse_consumer_sentiment(text):
    flat = normalize(text)
    start = flat.find('Consumer and Business Sentiment')
    if start < 0:
        start = flat.find('Consumer Sentiment')
    if start < 0:
        return 'NOT_FOUND'
    end = flat.find('Federal Budget Deficit and Debt', start)
    if end < 0:
        end = flat.find('Federal Budget', start)
    if end < 0:
        end = flat.find('Monetary Policy', start)
    if end < 0:
        end = len(flat)
    sec = flat[start:end]
    pats = [
        r'(?:University of Michigan|Reuters/Michigan|Reuters and the University of Michigan|Michigan)\\s+consumer sentiment(?: survey)?["'^.]{0,200}?(?:stood at|was|reached|rose to|fell to|declined to|trended lower, reaching|climbed to|recorded|stood at)'"\\s+([\\d.]+)',
        r'consumer sentiment index["'^.]{0,200}?(?:stood at|was|reached|rose to|fell to|declined to|trended lower, reaching|climbed to|recorded)'"\\s+([\\d.]+)',
        r'consumer sentiment survey["'^.]{0,200}?(?:reaching|stood at|was|rose to|fell to|declined to)'"\\s+([\\d.]+)',
    ]
    ms=[]
    for pat in pats:
        ms.extend(list(re.finditer(pat, sec, re.I)))
    if not ms:
        return 'NOT_FOUND'
    m = max(ms, key=lambda m: m.start())
    return m.group(1)


def parse_budget_deficit_pct(text):
    flat = normalize(text)
    start = flat.find('Federal Budget Deficit and Debt')
    if start < 0:
        start = flat.find('Federal Budget', 0)
    if start < 0:
        return 'NOT_FOUND'
    sec = flat[start:start+2000]
    pats = [
        r'federal budget deficit ["'^.]{0,150}?to'"\\s+([\\d.]+) percent of GDP',
        r'deficit ["'^.]{0,150}?to'"\\s+([\\d.]+) percent of GDP',
        r'budget deficit ["'^.]{0,150}?(['"\\d.]+) percent of GDP',
    ]
    for pat in pats:
        m = re.search(pat, sec, re.I)
        if m:
            return m.group(1)
    return 'NOT_FOUND'


def parse_ind_tax(text):
    flat = normalize(text)
    start = flat.find('Second-Quarter Receipts')
    if start < 0:
        start = flat.find('First-Quarter Receipts')
    if start < 0:
        start = flat.find('Budget Results and Financing')
    if start < 0:
        return 'NOT_FOUND'
    sec = flat[start:start+5000]
    pats = [
        r'Individual income tax receipts, net of refunds, were\\s+\\"'$(['"\\d.]+) billion\\s+for the ([a-zA-Z-]+) quarter of fiscal year\\s+(20\\d{2})',
        r'Individual income tax receipts["'^.]{0,120}?were'"\\s+\\"'$(['"\\d.]+) billion',
    ]
    for pat in pats:
        m = re.search(pat, sec, re.I)
        if m:
            return m.group(1)
    return 'NOT_FOUND'


def table_section(text, start, end=None):
    i = text.find(start)
    if i < 0:
        return ''
    j = text.find(end, i+len(start)) if end else -1
    return text[i:j] if j>i else text[i:]


def parse_first_annual_row_firstnum(section_text):
    for line in section_text.splitlines():
        if re.match(r'"'^20'"\\d{2}\\s*\\.{3,}', line.strip()):
            nums = re.findall(r'-?\\d[\\d,]*', line)
            if nums:
                return nums[0]
    return 'NOT_FOUND'


def parse_first_annual_row_lastnum(section_text):
    for line in section_text.splitlines():
        if re.match(r'"'^20'"\\d{2}\\s*\\.{3,}', line.strip()):
            nums = re.findall(r'-?\\d[\\d,]*', line)
            if nums:
                return nums[-1]
    return 'NOT_FOUND'


def parse_fd6(text):
    intro = table_section(text, 'Debt Subject to Statutory Limit', 'TABLE FD-7.')
    if re.search(r'statutory debt limit["'^'"\\n]{0,300}?suspended|debt limit has been suspended|shall not apply', intro, re.I|re.S):
        return 'suspended'
    sec = table_section(text, 'TABLE FD-6.—Debt Subject to Statutory Limit', 'TABLE FD-7.')
    return parse_first_annual_row_firstnum(sec)


def parse_total_receipts(text):
    flat = normalize(text)
    start = flat.find('Total On- and Off-Budget Results and Financing of the U.S. Government')
    if start < 0:
        return 'NOT_FOUND', 'NOT_FOUND'
    sec = flat[start:start+3000]
    m = re.search(r'Total receipts["'^'"\\d-]*([\\d,.-]+)\\s+([\\d,.-]+)\\s+On-budget receipts', sec, re.I)
    if not m:
        return 'NOT_FOUND', 'NOT_FOUND'
    return m.group(1), m.group(2)


def parse_net_ind_tax(text):
    flat = normalize(text)
    start = flat.find('Second-Quarter Receipts')
    if start < 0:
        start = flat.find('First-Quarter Receipts')
    if start < 0:
        start = flat.find('Budget Results and Financing')
    sec = flat[start:start+2000]
    m = re.search(r'Individual income tax receipts, net of refunds, were\\s+\\"'$(['"\\d.]+) billion', sec, re.I)
    return m.group(1) if m else 'NOT_FOUND'


def parse_percap(text):
    sec = table_section(text, 'Comparative totals of currency and coins in circulation', 'Sept. 30, 2005')
    # better isolate from heading to annual summary line
    if not sec:
        sec = table_section(text, 'Comparative totals of currency and coins in circulation—selected dates', None)
    lines = [ln.strip() for ln in sec.splitlines() if ln.strip()]
    for i,ln in enumerate(lines):
        if re.match(r'"'^(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)'"\\.?.*20\\d{2}', ln):
            nums=[]
            j=i+1
            while j < len(lines) and len(nums) < 2:
                if re.fullmatch(r'[\\d,]+', lines[j]):
                    nums.append(lines[j])
                j+=1
            if len(nums) >= 2:
                return nums[1]
    return 'NOT_FOUND'


def parse_esf_assets(text):
    sec = table_section(text, 'TABLE ESF-1.—Balances', 'TABLE ESF-2.')
    # Find total assets row and take the last numeric value on the next few lines.
    lines = sec.splitlines()
    for i, ln in enumerate(lines):
        if 'Total assets' in ln:
            nums=[]
            j=i
            while j < len(lines) and len(nums) < 3:
                nums.extend(re.findall(r'-?\\d[\\d,]*', lines[j]))
                j += 1
            if nums:
                return nums[-1]
    return 'NOT_FOUND'


def parse_fcp_rate(text):
    sec = table_section(text, 'TABLE FCP-I-1.—Weekly Report of Major Market Participants', 'TABLE FCP-I-2.')
    lines = [ln.rstrip() for ln in sec.splitlines()]
    vals = []
    i=0
    while i < len(lines):
        ln=lines[i].strip()
        if re.match(r'"'^'"\\d{2}/\\d{2}/20\\d{2}', ln):
            nums=[]
            j=i
            while j < len(lines) and len(nums) < 4:
                nums.extend(re.findall(r'n\\.a\\.|-?\\d+(?:\\.\\d+)?', lines[j]))
                j += 1
            if len(nums) >= 4:
                vals.append((ln, nums[:4]))
            i=j
        else:
            i+=1
    return vals[-1][1][3] if vals else 'NOT_FOUND'

for path in ['/mnt/data/LSF/data/officeqa/text/treasury_bulletin_2013_06.txt','/mnt/data/LSF/data/officeqa/text/treasury_bulletin_2025_06.txt']:
