        if re.match(r'"'^(?:20'"\\d{2}\\s*[–-]\\s*[A-Za-z]|(?:Jan|Feb|Mar|Apr|May|Jun|June|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\\.?\\s*)', s):
            vals=[]
            j=i+1
            while j < len(ls):
                t=ls[j]
                if re.match(r'"'^20'"\\d{2}\\s*\\.{1,}', t) and ' - ' not in t:
                    break
                if re.match(r'"'^20'"\\d{2}\\s*-\\s*', t):
                    break
                if re.match(r'"'^(?:20'"\\d{2}\\s*[–-]\\s*[A-Za-z]|(?:Jan|Feb|Mar|Apr|May|Jun|June|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\\.?\\s*)', t):
                    break
                if re.fullmatch(r'-?[\\d,]+(?:\\.\\d+)?', t):
                    vals.append(t)
                j += 1
            if vals:
                latest=vals
    if latest: return latest[0]
    return parse_first_block_annual(sec,'first')

def parse_percap(text):
    m2=re.search(r'Comparative totals of currency and coins in circulation[\\s\\S]{0,1200}', text, re.I)
    if not m2: return 'NOT_FOUND'
    sec=text[m2.start():]
    lines=table_lines(sec)
    for i,ln in enumerate(lines):
        if re.match(r'"'^(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)'"\\.?\\s+\\d{1,2},\\s+20\\d{2}', ln):
            nums=[]
            j=i+1
            while j < len(lines) and len(nums) < 2:
                if re.fullmatch(r'[\\d,]+', lines[j]): nums.append(lines[j])
                elif nums:
                    break
                j += 1
            if len(nums) >= 2: return nums[1]
    return 'NOT_FOUND'

def parse_esf_assets(text):
    sec=extract_span(text, r'(?m)"'^TABLE ESF-1[''^'"\\n]*Balances', r'(?m)"'^TABLE ESF-2'"\\b')
    lines=table_lines(sec)
    for i,ln in enumerate(lines):
        if 'Total assets' in ln:
            vals=[]
            j=i+1
            while j < len(lines):
                t=lines[j]
                if not t:
                    if vals: break
                    j += 1; continue
                if re.fullmatch(r'-?[\\d,]+(?:\\.\\d+)?', t):
                    vals.append(t)
                    j += 1
                    continue
                break
            if vals: return vals[-1]
    return 'NOT_FOUND'

def parse_fcp_rate(text):
    sec=extract_span(text, r'(?m)"'^TABLE FCP-I-1[''^'"\\n]*Weekly Report of Major Market Participants', r'(?m)"'^TABLE FCP-I-2'"\\b')
    lines=table_lines(sec)
    latest=None
    for i,ln in enumerate(lines):
        if re.match(r'"'^'"\\d{2}/\\d{2}/\\d{2,4}', ln):
            vals=[]
            j=i+1
            while j < len(lines) and len(vals) < 4:
                t=lines[j]
                if re.fullmatch(r'-?[\\d,]+(?:\\.\\d+)?|n\\.a\\.', t):
                    vals.append(t)
                j += 1
            if len(vals) >= 4:
                latest=vals[:4]
    return latest[3] if latest else 'NOT_FOUND'

def parse_receipts(text):
    sec=extract_span(text, r'Total On- and Off-Budget Results and Financing of the U\\.S\\. Government', r'Second-Quarter Net Budget Receipts by Source')
    lines=table_lines(sec)
    def row(label):
        for i,ln in enumerate(lines):
            if label in ln:
                vals=[]
                j=i+1
                while j < len(lines):
                    t=lines[j]
                    if re.match(r'"'^[A-Z].*(?:receipts|outlays|deficit|surplus|financing)'"', t):
                        break
                    if re.fullmatch(r'-?[\\d,]+(?:\\.\\d+)?', t):
                        vals.append(t)
                    j += 1
                return vals
        return []
    receipts=row('Total receipts')
    deficit=row('Total surplus or deficit')
    return (receipts[1] if len(receipts)>=2 else 'NOT_FOUND', deficit[1] if len(deficit)>=2 else 'NOT_FOUND')

def parse_ind_tax(text):
    for start in ['Second-Quarter Receipts','First-Quarter Receipts','Budget Results and Financing']:
        idx=text.find(start)
        if idx >= 0:
            sec=' '.join(text[idx:idx+4000].split())
            m=re.search(r'Individual income tax receipts, net of refunds, were\\s+\\"'$(['"\\d.]+) billion', sec, re.I)
            if m: return m.group(1)
    return 'NOT_FOUND'

def parse_gdp(text):
    flat=norm(text)
    m=re.search(r'real GDP(?: growth)?\\s+(advanced|grew|increased|rose|expanded|accelerated|declined|fell|contracted|shrank)\\s+([\\d.]+) percent(?: at an annual rate)?(?: in| during) the (first|second|third|fourth) quarter of (20\\d{2})', flat, re.I)
    if not m:
        m=re.search(r'real GDP(?: growth)?\\s+(advanced|grew|increased|rose|expanded|accelerated|declined|fell|contracted|shrank)\\s+([\\d.]+) percent(?: at an annual rate)?', flat, re.I)
        if not m: return 'NOT_FOUND'
    verb=m.group(1).lower(); num=m.group(2)
    if verb in {'declined','fell','contracted','shrank'} and not num.startswith('-'):
        return '-' + num
    return num

def parse_unemp(text):
    flat=norm(text)
    pat=r'(?:The|the) unemployment rate.*?(?:peaked at|reaching|stood at|was|rose to|declined to|fell to|dropped to|trended lower, reaching|trended lower to|moved to|remained at)\\s+([\\d.]+) percent\\s+(?:in|as of)\\s+([A-Za-z]+\\s+20\\d{2})'
    ms=[m for m in re.finditer(pat, flat, re.I|re.S) if 'U-6' not in m.group(0)]
    return ms[-1].group(1) if ms else 'NOT_FOUND'

def parse_payroll(text):
    flat=norm(text)
    msec = None
    for start,end in [('Labor Markets','Inflation'),('Labor Markets and Wages','Consumer and Business Sentiment'),('Labor Markets and Wages','Federal Budget')]:
        i=flat.find(start)
        if i>=0:
            j=flat.find(end, i)
            msec=flat[i:j if j>=0 else len(flat)]
            break
    if not msec: return 'NOT_FOUND'
    pats=[
        r'average monthly gain of\\s+([\\d,]+) jobs',
        r'average monthly loss of\\s+([\\d,]+) jobs',
        r'average monthly gain of\\s+([\\d,]+) per month',
        r'average monthly\\s+([\\d,]+) jobs',
        r'([\\d,]+) per month on average',
        r'average\\s+([\\d,]+) jobs in',
        r'average monthly growth of\\s+([\\d,]+)',
        r'rose an average of\\s+([\\d,]+) per month',
        r'averaged\\s+([\\d,]+) per month',
    ]
    ms=[]
    for pat in pats: ms.extend(list(re.finditer(pat, msec, re.I|re.S)))
    return ms[-1].group(1) if ms else 'NOT_FOUND'

def parse_sentiment(text):
    sec=first_paragraph(text, r'Consumer and Business Sentiment', r'Federal Budget Deficit and Debt')
    if not sec:
        sec=first_paragraph(text, r'Consumer and Business Sentiment', r'Monetary Policy')
    if not sec:
        sec=first_paragraph(text, r'Consumer Sentiment', r'Federal Budget')
    nums=[m.group(1) for m in re.finditer(r'(?:reaching|stood at|was|rose to|fell to|declined to|climbed to|remained at)\\s+([\\d.]+)', sec, re.I|re.S)]
    return nums[-1] if nums else 'NOT_FOUND'

def parse_budget_pct(text):
    sec=first_paragraph(text, r'Federal Budget Deficit and Debt', r'Economic Policy')
    if not sec:
        sec=first_paragraph(text, r'Federal Budget and Debt', r'Economic Policy')
    if not sec:
        sec=first_paragraph(text, r'Federal Budget Deficit and Debt', r'Monetary Policy')
    for pat in [r'equal to\\s+([\\d.]+)\\s+percent of GDP', r'as a percentage of GDP to\\s+([\\d.]+)\\s+percent', r'to\\s+([\\d.]+)\\s+percent of GDP']:
        m=re.search(pat, sec, re.I|re.S)
        if m: return m.group(1)
    return 'NOT_FOUND'

answers={}
for doc in obj['documents']:
    text=pathlib.Path(doc['doc_path']).read_text(errors='ignore')
    rec, deficit=parse_receipts(text)
    answers[doc['doc_name']]={
        questions[0]: issue_from_text(text, doc['doc_name']),
        questions[1]: parse_gdp(text),
        questions[2]: parse_unemp(text),
        questions[3]: parse_payroll(text),
        questions[4]: parse_sentiment(text),
        questions[5]: parse_budget_pct(text),
        questions[6]: rec,
        questions[7]: deficit,
        questions[8]: parse_ind_tax(text),
        questions[9]: parse_fd1(text),
        questions[10]: parse_fd2(text),
        questions[11]: parse_fd6(text),
        questions[12]: parse_fd5(text),
        questions[13]: parse_percap(text),
        questions[14]: parse_esf_assets(text),
        questions[15]: parse_fcp_rate(text),
    }

out={'answers': answers}
out_path.write_text(json.dumps(out, indent=2, ensure_ascii=False))
